package mz.bam.seeky.android;
import android.content.*;import android.database.*;import android.database.sqlite.*;import org.json.*;import java.io.*;import java.util.*;import java.util.zip.*;
/** Cloud recovery replaces a workspace exactly, preserving IDs and reading references.
 * Every payload is validated/staged before a transaction over the two attached databases.
 */
final class StudySnapshot {
 static JSONObject manifest(File archive)throws Exception{try(ZipFile zip=new ZipFile(archive)){ZipEntry entry=zip.getEntry("study.json");if(entry==null)throw new IOException("Cópia sem manifesto.");byte[] b;try(InputStream in=zip.getInputStream(entry)){b=ContentText.read(in,8388609);}if(b.length>8388608)throw new IOException("Manifesto demasiado extenso.");String text=new String(b,"UTF-8");JsonBudget.check(text,12,150000);JSONObject root=new JSONObject(text);if(!Arrays.asList("seeky-studies-1","seeky-studies-2").contains(root.optString("format")))throw new IOException("Formato de cópia incompatível.");return root;}}
 static int restore(Context c,StudyStore db,File archive,long expectedRevision,String uid,long remoteRevision,String remoteId)throws Exception {
  JSONObject root=manifest(archive),tables=root.getJSONObject("tables");JSONObject state=root.optJSONObject("app_state");if(state==null)state=new JSONObject();validateState(state);
  List<File> staged=new ArrayList<>(),oldFiles=new ArrayList<>();Map<Long,String> paths=new HashMap<>();Set<Long> courseIds=new HashSet<>(),materialIds=new HashSet<>(),subjectIds=new HashSet<>(),cardIds=new HashSet<>();courseIds.add(0L);subjectIds.add(0L);materialIds.add(0L);cardIds.add(0L);int count=0;boolean committed=false,attached=false;
  for(StudyStore.Row m:db.rows("materials",null,null,null,10000))oldFiles.add(new File(m.s("path")));
  try(ZipFile zip=new ZipFile(archive)){
   JSONArray mats=tables.getJSONArray("materials");List<Long> ids=new ArrayList<>();for(int i=0;i<mats.length();i++)ids.add(mats.getJSONObject(i).getLong("id"));StudyFiles.validateArchive(zip,ids);
   Map<String,List<ContentValues>> prepared=new LinkedHashMap<>();long total=0;
   for(String table:StudyStore.TABLES){JSONArray rows=tables.optJSONArray(table);if(rows==null){if(table.equals("practice")||table.equals("study_trash")||table.equals("courses")&&root.optString("format").equals("seeky-studies-1"))rows=new JSONArray();else throw new IOException("Falta uma tabela da cópia.");}if(rows.length()>10000)throw new IOException("Demasiados registos.");List<ContentValues> values=new ArrayList<>();Set<Long> unique=new HashSet<>();Set<String> columns=new HashSet<>();try(Cursor schema=db.getReadableDatabase().rawQuery("PRAGMA table_info("+table+")",null)){while(schema.moveToNext())columns.add(schema.getString(1));}
    for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);long id=row.getLong("id");if(id<=0||!unique.add(id))throw new IOException("Identificador repetido ou inválido.");StudyBackup.validate(table,row);ContentValues v=new ContentValues();Iterator<String> keys=row.keys();while(keys.hasNext()){String k=keys.next();if(k.equals("path"))continue;if(!columns.contains(k))throw new IOException("Campo de cópia desconhecido.");String value=row.getString(k);if(value.length()>1048576)throw new IOException("Campo demasiado extenso.");v.put(k,value);}if(table.equals("courses"))courseIds.add(id);if(table.equals("subjects"))subjectIds.add(id);if(table.equals("materials"))materialIds.add(id);if(table.equals("cards"))cardIds.add(id);
     if(table.equals("materials")){File f=new File(StudyFileProvider.directory(c),UUID.randomUUID()+"."+StudyFiles.extension(row.getString("name")));staged.add(f);String hash;try(InputStream in=zip.getInputStream(zip.getEntry("materials/"+id))){hash=StudyFiles.copy(in,f,134217728,()->Thread.currentThread().isInterrupted());}if(!hash.equals(row.getString("hash"))||f.length()!=row.getLong("bytes"))throw new IOException("O material não passou a verificação de integridade.");total+=f.length();if(total>StudyBackup.MAX)throw new IOException("Biblioteca demasiado extensa.");v.put("path",f.getPath());paths.put(id,f.getPath());}values.add(v);count++;}
    prepared.put(table,values);
   }
   for(List<ContentValues> rows:prepared.values())for(ContentValues row:rows){if(row.containsKey("course")&&!courseIds.contains(row.getAsLong("course")))throw new IOException("Curso ausente.");if(row.containsKey("subject")&&!subjectIds.contains(row.getAsLong("subject")))throw new IOException("Disciplina ausente.");if(row.containsKey("material")&&!materialIds.contains(row.getAsLong("material")))throw new IOException("Material ausente.");if(row.containsKey("card")&&!cardIds.contains(row.getAsLong("card")))throw new IOException("Cartão ausente.");}
   JSONObject reader=root.optJSONObject("reader");Map<String,List<ContentValues>> readerValues=new LinkedHashMap<>();for(String table:new String[]{"draft","bookmark"}){List<ContentValues> values=new ArrayList<>();JSONArray arr=reader==null?null:reader.optJSONArray(table);if(arr!=null){if(arr.length()>20000)throw new IOException("Demasiadas anotações.");for(int i=0;i<arr.length();i++){JSONObject item=arr.getJSONObject(i);long material=item.getLong("material_id");if(material<=0||!materialIds.contains(material)||item.getInt("segment")<0)throw new IOException("Origem de anotação inválida.");ContentValues v=new ContentValues();v.put("uri",StudyFileProvider.uri(c,material).toString());v.put("segment",item.getInt("segment"));if(table.equals("draft")){String text=item.getString("value"),digest=item.getString("digest"),marks=item.getString("marks");if(text.length()>1048576||!digest.matches("[a-f0-9]{64}"))throw new IOException("Texto anotado inválido.");JSONArray ranges=new JSONArray(marks);if(ranges.length()>1000)throw new IOException("Demasiadas marcas.");for(int j=0;j<ranges.length();j++){JSONObject m=ranges.getJSONObject(j);if(m.getInt("s")<0||m.getInt("e")<m.getInt("s")||m.getInt("e")>text.length()||!Arrays.asList("note","highlight","underline").contains(m.getString("k")))throw new IOException("Selecção de anotação inválida.");}v.put("digest",digest);v.put("value",text);v.put("marks",marks);}else{if(item.getInt("position")<0)throw new IOException("Marcador inválido.");v.put("position",item.getInt("position"));v.put("label",StudySchedule.valid(item.getString("label"),500,"Marcador"));v.put("created",item.getLong("created"));}values.add(v);}}readerValues.put(table,values);}
   try(ReaderStore init=new ReaderStore(c)){init.getWritableDatabase();}
   SQLiteDatabase sql=db.getWritableDatabase();sql.disableWriteAheadLogging();try{sql.execSQL("ATTACH DATABASE ? AS reader_sync",new Object[]{c.getDatabasePath("seeky-reader.db").getPath()});attached=true;sql.beginTransaction();try{if(StudyState.revision(db)!=expectedRevision)throw new IOException("Os dados deste telemóvel mudaram durante a recuperação. Repita a revisão da cópia.");String owner=StudyState.owner(db);if(!owner.isEmpty()&&!owner.equals(uid))throw new IOException("Os dados locais pertencem a outra conta.");for(String table:StudyStore.TABLES)sql.delete(table,null,null);for(Map.Entry<String,List<ContentValues>> group:prepared.entrySet())for(ContentValues row:group.getValue())sql.insertOrThrow(group.getKey(),null,row);
     String scope="content://"+c.getPackageName()+".study/%";for(String journal:new String[]{"edit_history","cut_clip"})sql.delete("reader_sync."+journal,"uri LIKE ?",new String[]{scope});for(String table:new String[]{"draft","bookmark"}){sql.delete("reader_sync."+table,"uri LIKE ?",new String[]{scope});for(ContentValues row:readerValues.get(table))sql.insertOrThrow("reader_sync."+table,null,row);}
     sql.execSQL("UPDATE study_meta SET revision=?,owner=?,remote_revision=?,remote_head=?,pending_prefs=? WHERE id=1",new Object[]{expectedRevision+1,uid,remoteRevision,remoteId,state.toString()});sql.setTransactionSuccessful();}finally{sql.endTransaction();}committed=true;
   }finally{if(attached)sql.execSQL("DETACH DATABASE reader_sync");sql.enableWriteAheadLogging();}
   StudyState.applyPrefs(c,db);for(File f:oldFiles)try{if(DiskWalker.inside(StudyFileProvider.directory(c).getCanonicalFile(),f.getCanonicalFile())&&!paths.containsValue(f.getPath()))f.delete();}catch(Exception ignored){}return count;
  }catch(Exception e){if(committed)throw new IOException("Os dados foram recuperados. As preferências pendentes serão reaplicadas ao abrir o aplicativo. "+e.getMessage(),e);throw e;}finally{if(!committed)for(File f:staged){f.delete();new File(f.getPath()+".part").delete();}}
 }
 static void validateState(JSONObject state)throws Exception{JSONObject s=state.optJSONObject("studies");if(s!=null){Iterator<String> keys=s.keys();while(keys.hasNext()){String k=keys.next();if(!StudyState.allowedPref(k)&&!k.equals("captured_timer_seconds"))throw new IOException("Preferência desconhecida.");Object v=s.get(k);if(k.equals("course")||k.equals("subject")||k.equals("daily_goal")||k.equals("captured_timer_seconds")||Arrays.asList("timer_acc","timer_limit","timer_elapsed","timer_wall","timer_started","timer_subject").contains(k)){if(!(v instanceof Number))throw new IOException("Preferência numérica inválida.");}else if(k.equals("timer_active")||k.equals("timer_paused")){if(!(v instanceof Boolean))throw new IOException("Estado de sessão inválido.");}else if(!(v instanceof String))throw new IOException("Preferência de texto inválida.");}if(s.has("daily_goal")&&(s.getInt("daily_goal")<5||s.getInt("daily_goal")>480))throw new IOException("Meta inválida.");if(s.optLong("timer_limit",1500)<1||s.optLong("timer_limit",1500)>7200||s.optLong("captured_timer_seconds",0)<0||s.optLong("captured_timer_seconds",0)>7200)throw new IOException("Temporizador inválido.");}JSONObject reader=state.optJSONObject("reader");if(reader!=null){if(reader.has("theme")&&!Arrays.asList("Claro","Escuro","Jade","Oceano","Coral","Âmbar","Rosa","Grafite").contains(reader.getString("theme")))throw new IOException("Tema inválido.");if(reader.has("reader_font")&&(reader.getDouble("reader_font")<12||reader.getDouble("reader_font")>34))throw new IOException("Letra inválida.");}JSONObject p=state.optJSONObject("positions");if(p!=null){Iterator<String> ids=p.keys();while(ids.hasNext()){String id=ids.next();if(!id.matches("[1-9][0-9]{0,18}"))throw new IOException("Posição inválida.");JSONObject pos=p.getJSONObject(id);if(pos.optInt("page",0)<0||pos.optInt("chapter",0)<0)throw new IOException("Página inválida.");}}}
}
